1	interface QuoteStep {
2	  op: "quote";
3	  items: { type: string }[];
4	}
5	
6	interface Scenario {
7	  customer: { yearsWithMHPCO: number };
8	  steps: QuoteStep[];
9	}
10	
11	interface QuoteResult {
12	  premium: number;
13	}
14	
15	const BASE_PREMIUM: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	};
22	
23	const PROCESSING_FEE = 5;
24	const FIRST_INSURANCE_SURCHARGE = 0.1;
25	
26	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
27	const COMPONENT_UNIT_PREMIUM = 25;
28	const COMPONENT_BLOCK_SIZE = 3;
29	const COMPONENT_BLOCK_PREMIUM = 60;
30	
31	const componentGroupBase = (count: number): number =>
32	  count === COMPONENT_BLOCK_SIZE
33	    ? COMPONENT_BLOCK_PREMIUM
34	    : count * COMPONENT_UNIT_PREMIUM;
35	
36	const componentsBase = (items: { type: string }[]): number => {
37	  const counts = new Map<string, number>();
38	  for (const item of items) {
39	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
40	  }
41	  let total = 0;
42	  for (const count of counts.values()) {
43	    total += componentGroupBase(count);
44	  }
45	  return total;
46	};
47	
48	const itemsBase = (items: { type: string }[]): number => {
49	  const mainBase = items
50	    .filter((item) => !COMPONENT_TYPES.has(item.type))
51	    .reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);
52	  const components = items.filter((item) => COMPONENT_TYPES.has(item.type));
53	  return mainBase + componentsBase(components);
54	};
55	
56	const quotePremium = (items: { type: string }[]): number => {
57	  const base = itemsBase(items);
58	  // Keep as `base + base * rate`, not `base * (1 + rate)`: the additive form
59	  // avoids IEEE-754 drift that would otherwise round wrong under Math.ceil.
60	  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE);
61	};
62	
63	export const runScenario = (scenario: Scenario): { results: QuoteResult[] } => {
64	  const results = scenario.steps.map((step) => ({
65	    premium: quotePremium(step.items),
66	  }));
67	  return { results };
68	};
